#if NET10_0_OR_GREATER
using System;
using System.Globalization;
using System.Numerics;

namespace EngineeringUnits;

/// <summary>
/// For the conversions between EngineeringUnits and EngineeringUnits.Fast in FastConversions.g.cs and FastBridge.g.cs (generated by
/// CodeGen.Fast). To Fast the exact value is rounded once to the nearest double, from Fast the double arrives as the shortest
/// decimal that rounds back to it - so Fast -> EngineeringUnits -> Fast gives the same bits.
/// </summary>
internal static class FastConversion
{
    /// <summary>
    /// The SI value of a quantity: the exact value it holds, rounded once to the nearest double. Not <c>As(XUnit.SI)</c>: that rounds
    /// to decimal's 28 decimal places first (1 µg/day loses digits) and (double)decimal itself can be 1 ulp off.
    /// </summary>
    public static double SI(BaseUnit value, UnitTypebase siUnit) =>
        value.Unit.IsSIUnit() && value.testValue is null
            ? ToDouble(value.NEWValue)                                              // already SI: the value it holds
            : ExactDouble.From(BaseUnitExtensions.GetValueAs(value, siUnit.Unit)); // exact Fraction conversion (also the Fraction a unit was created from)

    /// <summary>
    /// For ToClassic(): the shortest decimal that rounds back to <paramref name="si"/>, its round-trip ("R") digits:
    /// 0.1 -> 0.1m, 0.1 + 0.2 -> 0.30000000000000004m (the double constructors keep 15 significant digits: 0.3m).
    /// Digits beyond decimal's 28 decimal places are rounded off (1e-30 -> 0), as everywhere in EngineeringUnits.
    /// Null for NaN, ±Infinity and beyond ±7.9e28: decimal can't hold them, EngineeringUnits keeps them as a double.
    /// </summary>
    public static decimal? ShortestDecimal(double si)
    {
        // False for NaN and ±Infinity
        if (!(Math.Abs(si) < (double)decimal.MaxValue))
            return null;

        // (decimal)si keeps 15 significant digits. Two such decimals are at least 1e-15 apart (relative), what rounds to si spans
        // at most 2.2e-16: when it rounds back to si, it is the only one there - the shortest. The rest (16 or 17 digits, digits
        // beyond the 28th decimal place, and -0 as (decimal)-0d is 0) goes through the round-trip digits
        var fifteenDigits = (decimal)si;
        if (BitConverter.DoubleToInt64Bits(ToDouble(fifteenDigits)) == BitConverter.DoubleToInt64Bits(si))
            return fifteenDigits;

        Span<char> digits = stackalloc char[32];    // the longest is 24: -2.2250738585072014E-308
        si.TryFormat(digits, out var length, "R", CultureInfo.InvariantCulture);
        return decimal.Parse(digits[..length], NumberStyles.Float, CultureInfo.InvariantCulture);
    }

    private static double ToDouble(DecimalSafe value) => value.IsDecimal ? ToDouble(value.Value) : (double)value;

    // 10^0 .. 10^22: the powers of ten a double holds exactly
    private static readonly double[] ExactPowersOf10 =
        [1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10, 1e11, 1e12, 1e13, 1e14, 1e15, 1e16, 1e17, 1e18, 1e19, 1e20, 1e21, 1e22];

    /// <summary>
    /// Rounded once to the nearest double. (double)decimal is not: it rounds the 96 bit integer and the division by 10^scale
    /// separately, 1m / 3 gives 0.33333333333333337 instead of 0.3333333333333333.
    /// </summary>
    private static double ToDouble(decimal value)
    {
        Span<int> bits = stackalloc int[4];
        decimal.GetBits(value, bits);
        var low = (uint)bits[0] | (ulong)(uint)bits[1] << 32;

        // An integer up to 2^53 and 10^0 .. 10^22 are exact doubles, so one IEEE division rounds once - every value given as a
        // double (15 significant digits) takes this path. Longer ones are rounded from the exact integers
        var result = bits[2] == 0 && low <= 1UL << 53 && value.Scale <= 22
            ? low / ExactPowersOf10[value.Scale]
            : ExactDouble.Divide(new BigInteger(low) | new BigInteger((uint)bits[2]) << 64, BigInteger.Pow(10, value.Scale));

        return decimal.IsNegative(value) ? -result : result;                       // -0m stays -0
    }

}
#endif
